class Solution {
    private fun feasible(bloomDay:IntArray,m:Int,k:Int,day:Int):Boolean{
        var bouquets=0;
        var consecutive=0;
        for(bloom in bloomDay){
            if(bloom<=day){
                consecutive++;
                if(consecutive==k){
                    bouquets++;
                    consecutive=0
                }
            }else consecutive=0
        };
        return bouquets>=m
    };
    fun minDays(bloomDay:IntArray,m:Int,k:Int):Int{
        if(m.toLong()*k>bloomDay.size)return -1;
        var left=bloomDay.minOrNull()!!;
        var right=bloomDay.maxOrNull()!!;
        while(left<right){
            val middle=left+(right-left)/2;
            if(feasible(bloomDay,m,k,middle))right=middle else left=middle+1
        };
        return left
    }
}

